  8→	"net"
  9→	"strconv"
 10→	"sync"
 11→	"time"
 12→
 13→	"github.com/finalappstore/stupidsamba/internal/smb/command"
 14→)
 15→
 16→// 默认的服务端参数。
 17→const (
 18→	// DefaultPort 是 SMB Direct TCP 端口。
 19→	DefaultPort = 445
 20→
 21→	// DefaultMaxConnections 是并发连接数上限（AGENTS.md §8 资源限制）。
 22→	DefaultMaxConnections = 256
 23→
 24→	// DefaultIdleTimeout 是连接空闲多久没有收到任何帧就断开。
 25→	//
 26→	// 取值偏大：macOS Finder 挂载后可能长时间不发请求，
 27→	// 但 SMB2 客户端通常有 keepalive（ECHO）。
 28→	DefaultIdleTimeout = 15 * time.Minute
 29→
 30→	// DefaultWriteTimeout 是单次写出的超时，用于淘汰慢客户端。
 31→	DefaultWriteTimeout = 60 * time.Second
 32→
 33→	// shutdownPollInterval 是优雅关闭时轮询连接数的间隔。
 34→	shutdownPollInterval = 20 * time.Millisecond
 35→)
 36→
 37→// ErrServerClosed 在 Serve 因 Shutdown/Close 正常返回时给出。
 38→var ErrServerClosed = errors.New("smb server: closed")
 39→
 40→// Options 是 Server 的装配参数。
 41→type Options struct {
 42→	// Addresses 是要监听的 IP 列表。留空表示监听所有地址。
 43→	//
 44→	// 需求约定（AGENTS.md §6）：地址是**列表**，端口只有**一个**。
 45→	Addresses []string
 46→	// Port 是监听端口，0 表示 DefaultPort。
 47→	Port int
 48→
 49→	// Settings 是 SMB 协议层设置（共享表、认证后端、方言区间……）。
 50→	Settings *command.Settings
 51→
 52→	// MaxConnections 是并发连接上限，0 表示 DefaultMaxConnections。
 53→	MaxConnections int
 54→	// IdleTimeout / WriteTimeout 为 0 时使用默认值，负数表示不设超时。
 55→	IdleTimeout  time.Duration
 56→	WriteTimeout time.Duration
 57→	// MaxFrameSize 是单帧上限，0 表示 DefaultMaxFrameSize。
 58→	MaxFrameSize int
 59→
 60→	// Logger 为 nil 时使用 slog.Default()。
 61→	Logger *slog.Logger
 62→}
 63→
 64→func (o *Options) port() int {
 65→	if o.Port <= 0 {
 66→		return DefaultPort
 67→	}
 68→	return o.Port
 69→}
 70→
 71→func (o *Options) maxConnections() int {
 72→	if o.MaxConnections <= 0 {
 73→		return DefaultMaxConnections
 74→	}
 75→	return o.MaxConnections
 76→}
 77→
 78→func (o *Options) idleTimeout() time.Duration {
 79→	switch {
 80→	case o.IdleTimeout < 0:
 81→		return 0
 82→	case o.IdleTimeout == 0:
 83→		return DefaultIdleTimeout
 84→	default:
 85→		return o.IdleTimeout
 86→	}
 87→}
 88→
 89→func (o *Options) writeTimeout() time.Duration {
 90→	switch {
 91→	case o.WriteTimeout < 0:
 92→		return 0
 93→	case o.WriteTimeout == 0:
 94→		return DefaultWriteTimeout
 95→	default:
 96→		return o.WriteTimeout
 97→	}
 98→}
 99→
100→// Server 监听若干地址并为每条连接跑一个 Connection。
101→type Server struct {
102→	opts Options
103→	log  *slog.Logger
104→
105→	mu        sync.Mutex
106→	listeners []net.Listener
107→	conns     map[*Connection]struct{}
108→	closed    bool
109→	doneCh    chan struct{}
110→
111→	// wg 覆盖 accept goroutine 与每条连接的 serve goroutine。
112→	wg sync.WaitGroup
113→}
114→
115→// New 创建服务端。此时还没有绑定端口。
116→func New(opts Options) (*Server, error) {
117→	if opts.Settings == nil {
118→		return nil, errors.New("smb server: Options.Settings 不能为空")
119→	}
120→	if opts.Settings.Auth == nil {
121→		return nil, errors.New("smb server: Settings.Auth 不能为空")
122→	}
123→	if len(opts.Settings.Shares) == 0 {
124→		return nil, errors.New("smb server: 至少要配置一个共享")
125→	}
126→	log := opts.Logger
127→	if log == nil {
128→		log = slog.Default()
129→	}
130→	// IPC$ 上的 srvsvc 不是可选项：没有它客户端无法枚举共享
131→	// （`smbclient -L`、Finder 的 smb://host、资源管理器都靠它）。
132→	// 装配层没有显式提供后端时在这里补上默认实现。
133→	if opts.Settings.Pipes == nil {
134→		opts.Settings.Pipes = NewPipeOpener(opts.Settings)
135→	}
136→	return &Server{
137→		opts:   opts,
138→		log:    log,
139→		conns:  make(map[*Connection]struct{}),
140→		doneCh: make(chan struct{}),
141→	}, nil
142→}
143→
144→// Listen 绑定 Options 里配置的全部地址。
145→//
146→// 任何一个地址绑定失败都会回滚已经绑定的监听套接字并返回错误 ——
147→// 部分成功会让运维困惑（"服务起来了但某个网卡上连不上"）。
148→func (s *Server) Listen() error {
149→	port := strconv.Itoa(s.opts.port())
150→
151→	addrs := s.opts.Addresses
152→	if len(addrs) == 0 {
153→		// 空列表 = 所有地址。Go 的 "tcp" + 空 host 会同时覆盖 IPv4/IPv6
154→		// （双栈套接字），无需分别监听 0.0.0.0 与 ::。
155→		addrs = []string{""}
156→	}
157→
158→	var ls []net.Listener
159→	for _, a := range addrs {
160→		l, err := net.Listen("tcp", net.JoinHostPort(a, port))
161→		if err != nil {
162→			for _, prev := range ls {
163→				_ = prev.Close()
164→			}
165→			where := a
166→			if where == "" {
167→				where = "所有地址"
168→			}
169→			return fmt.Errorf("smb server: 监听 %s:%s 失败: %w", where, port, err)
170→		}
171→		ls = append(ls, l)
172→	}
173→
174→	s.mu.Lock()
175→	defer s.mu.Unlock()
176→	if s.closed {
177→		for _, l := range ls {
178→			_ = l.Close()
179→		}
180→		return ErrServerClosed
181→	}
182→	s.listeners = append(s.listeners, ls...)
183→	return nil
184→}
185→
186→// Addrs 返回已绑定的本地地址，便于测试里取随机端口。
187→func (s *Server) Addrs() []net.Addr {
188→	s.mu.Lock()
189→	defer s.mu.Unlock()
190→	out := make([]net.Addr, 0, len(s.listeners))
191→	for _, l := range s.listeners {
192→		out = append(out, l.Addr())
193→	}
194→	return out
195→}
196→
197→// Serve 在已绑定的监听套接字上接受连接，直到 ctx 取消或 Shutdown 被调用。
198→//
199→// 返回 ErrServerClosed 表示正常停止。
200→func (s *Server) Serve(ctx context.Context) error {
201→	s.mu.Lock()
202→	if s.closed {
203→		s.mu.Unlock()
204→		return ErrServerClosed
205→	}
206→	if len(s.listeners) == 0 {
207→		s.mu.Unlock()
208→		return errors.New("smb server: 尚未调用 Listen")
209→	}
210→	listeners := append([]net.Listener(nil), s.listeners...)
211→	s.mu.Unlock()
212→
213→	// ctx 取消时主动关闭监听套接字，让 Accept 立刻返回。
214→	stop := context.AfterFunc(ctx, func() { s.closeListeners() })
215→	defer stop()
216→
217→	for _, l := range listeners {
218→		s.wg.Add(1)
219→		go func(l net.Listener) {
220→			defer s.wg.Done()
221→			s.acceptLoop(ctx, l)
222→		}(l)
223→	}
224→
225→	<-s.doneCh
226→	return ErrServerClosed
227→}
228→
229→// ListenAndServe 是 Listen + Serve 的组合。
230→func (s *Server) ListenAndServe(ctx context.Context) error {
231→	if err := s.Listen(); err != nil {
232→		return err
233→	}
234→	return s.Serve(ctx)
235→}
236→
237→func (s *Server) acceptLoop(ctx context.Context, l net.Listener) {
238→	// 临时错误（EMFILE、ECONNABORTED 等）退避重试，不要让 accept 循环退出。
239→	var backoff time.Duration
240→
241→	for {
242→		conn, err := l.Accept()
243→		if err != nil {
244→			if s.isClosed() || ctx.Err() != nil {
245→				return
246→			}
247→			var ne net.Error
248→			if errors.As(err, &ne) && ne.Timeout() {
249→				continue
250→			}
251→			if errors.Is(err, net.ErrClosed) {
252→				return
253→			}
254→			// 未知错误：退避后重试，避免 CPU 空转。
255→			if backoff == 0 {
256→				backoff = 5 * time.Millisecond
257→			} else if backoff < time.Second {
258→				backoff *= 2
259→			}
260→			s.log.Warn("accept 失败，稍后重试", "listener", l.Addr().String(), "err", err, "backoff", backoff)
261→			select {
262→			case <-time.After(backoff):
263→			case <-s.doneCh:
264→				return
265→			case <-ctx.Done():
266→				return
267→			}
268→			continue
269→		}
270→		backoff = 0
271→
272→		if !s.trackConn(ctx, conn) {
273→			// 超出并发上限：直接断开。SMB 没有"服务器忙"的传输层表达，
274→			// 关闭连接是唯一选择。
275→			s.log.Warn("并发连接数已达上限，拒绝新连接",
276→				"remote", conn.RemoteAddr().String(), "max", s.opts.maxConnections())
277→			_ = conn.Close()
278→		}
279→	}
280→}
281→
282→// trackConn 登记连接并启动其服务 goroutine。超出上限时返回 false。
283→func (s *Server) trackConn(ctx context.Context, nc net.Conn) bool {
284→	c := newConnection(s, nc)
285→
286→	s.mu.Lock()
287→	if s.closed {
288→		s.mu.Unlock()
289→		return false
290→	}
291→	if len(s.conns) >= s.opts.maxConnections() {
292→		s.mu.Unlock()
293→		return false
294→	}
295→	s.conns[c] = struct{}{}
296→	s.mu.Unlock()
297→
298→	s.wg.Add(1)
299→	go func() {
300→		defer s.wg.Done()
301→		defer s.untrackConn(c)
302→		c.serve(ctx)
303→	}()
304→	return true
305→}
306→
307→func (s *Server) untrackConn(c *Connection) {
308→	s.mu.Lock()
309→	delete(s.conns, c)
310→	s.mu.Unlock()
311→}
312→
313→func (s *Server) isClosed() bool {
314→	s.mu.Lock()
315→	defer s.mu.Unlock()
316→	return s.closed
317→}
318→
319→// ConnectionCount 返回当前活跃连接数，用于日志与测试。
320→func (s *Server) ConnectionCount() int {
321→	s.mu.Lock()
322→	defer s.mu.Unlock()
323→	return len(s.conns)
324→}
325→
326→// closeListeners 关闭全部监听套接字并唤醒 Serve。
327→func (s *Server) closeListeners() {
328→	s.mu.Lock()
329→	if s.closed {
330→		s.mu.Unlock()
331→		return
332→	}
333→	s.closed = true
334→	ls := s.listeners
335→	s.listeners = nil
336→	close(s.doneCh)
337→	s.mu.Unlock()
338→
339→	for _, l := range ls {
340→		_ = l.Close()
341→	}
342→}
343→
344→// Shutdown 优雅关闭：先停止接受新连接，再等待既有连接自然结束。
345→//
346→// ctx 超时后强制断开所有仍在的连接。
347→func (s *Server) Shutdown(ctx context.Context) error {
348→	s.closeListeners()
349→
350→	// 轮询等待连接自然退出。
351→	ticker := time.NewTicker(shutdownPollInterval)
352→	defer ticker.Stop()
353→	for {
354→		if s.ConnectionCount() == 0 {
355→			s.wg.Wait()
356→			return nil
357→		}
358→		select {
359→		case <-ctx.Done():
360→			s.Close()
361→			s.wg.Wait()
362→			return ctx.Err()
363→		case <-ticker.C:
364→		}
365→	}
366→}
367→
368→// Close 立刻关闭监听与全部连接，不等待请求处理完成。
369→func (s *Server) Close() {
370→	s.closeListeners()
371→
372→	s.mu.Lock()
373→	conns := make([]*Connection, 0, len(s.conns))
374→	for c := range s.conns {
375→		conns = append(conns, c)
376→	}
377→	s.mu.Unlock()
378→
379→	for _, c := range conns {
380→		c.Close()
381→	}
382→}
