 1→package command
 2→
 3→import (
 4→	"github.com/finalappstore/stupidsamba/internal/auth"
 5→	"github.com/finalappstore/stupidsamba/internal/smb/status"
 6→	"github.com/finalappstore/stupidsamba/internal/smb/wire"
 7→)
 8→
 9→func init() {
10→	register(wire.CommandTreeConnect, true, false, handleTreeConnect)
11→	register(wire.CommandTreeDisconnect, true, true, handleTreeDisconnect)
12→}
13→
14→// handleTreeConnect 处理 SMB2 TREE_CONNECT（MS-SMB2 §3.3.5.7）。
15→//
16→// 路径形如 `\\SERVER\share`。服务端**忽略主机名部分**，只取最后一段做
17→// 大小写不敏感匹配（protocol-notes §7）。
18→func handleTreeConnect(ctx *Context) error {
19→	req, err := wire.ParseTreeConnectRequest(ctx.Msg)
20→	if err != nil {
21→		ctx.Log.Debug("TREE_CONNECT 请求解析失败", "remote", ctx.Conn.RemoteAddr, "err", err)
22→		return status.InvalidParameter
23→	}
24→
25→	name := req.ShareName()
26→	if name == "" {
27→		return status.BadNetworkName
28→	}
29→
30→	share := ctx.Conn.Settings.FindShare(name)
31→	if share == nil {
32→		ctx.Log.Debug("共享不存在", "remote", ctx.Conn.RemoteAddr, "share", name)
33→		return status.BadNetworkName
34→	}
35→
36→	id := ctx.Session.Identity()
37→	if !share.Authorize(id) {
38→		ctx.Log.Warn("共享访问被拒绝",
39→			"remote", ctx.Conn.RemoteAddr, "share", share.Name, "user", identityName(id))
40→		return status.AccessDenied
41→	}
42→
43→	tree, st := ctx.Session.NewTree(share)
44→	if st != status.Success {
45→		return st
46→	}
47→	ctx.Tree = tree
48→	ctx.Chain.Tree = tree
49→	ctx.RespHeader.TreeID = tree.ID
50→
51→	resp := &wire.TreeConnectResponse{
52→		ShareType:     share.Type,
53→		MaximalAccess: share.MaximalAccess(),
54→	}
55→	if !share.IsIPC() {
56→		// MANUAL_CACHING(0x0) + FORCE_LEVELII_OPLOCK：我们不实现 oplock/lease，
57→		// 让客户端知道最多只能拿到 level II，避免它反复申请（protocol-notes §7）。
58→		resp.ShareFlags = wire.ShareFlagManualCaching | wire.ShareFlagForceLevelIIOplock
59→	}
60→	ctx.Out = resp.Append(ctx.Out)
61→
62→	ctx.Log.Debug("树连接建立",
63→		"remote", ctx.Conn.RemoteAddr, "session", ctx.Session.ID,
64→		"tree", tree.ID, "share", share.Name, "read_only", share.ReadOnly)
65→	return nil
66→}
67→
68→// handleTreeDisconnect 处理 SMB2 TREE_DISCONNECT（MS-SMB2 §3.3.5.8）。
69→func handleTreeDisconnect(ctx *Context) error {
70→	if _, err := wire.ParseTreeDisconnectRequest(ctx.Msg); err != nil {
71→		return status.InvalidParameter
72→	}
73→	id := ctx.Tree.ID
74→	if st := ctx.Session.RemoveTree(id); st != status.Success {
75→		return st
76→	}
77→	if ctx.Chain.Tree != nil && ctx.Chain.Tree.ID == id {
78→		ctx.Chain.Tree = nil
79→	}
80→	ctx.Chain.LastOpen = nil
81→
82→	ctx.Out = (&wire.TreeDisconnectResponse{}).Append(ctx.Out)
83→	return nil
84→}
85→
86→// identityName 返回用于日志的用户名（永远不打印口令或密钥）。
87→func identityName(id *auth.Identity) string {
88→	if id == nil {
89→		return "<nil>"
90→	}
91→	if id.Anonymous {
92→		return "<anonymous>"
93→	}
94→	if id.User == "" {
95→		return "<empty>"
96→	}
97→	return id.User
98→}
99→

