 17→// 打包成一帧」的常用写法，不实现的话 Explorer 会非常慢。
 18→func (c *Context) resolveOpen(fid wire.FileID) (*Open, error) {
 19→	if fid.IsCompound() {
 20→		if c.Chain.LastOpen == nil {
 21→			return nil, status.FileClosed
 22→		}
 23→		return c.Chain.LastOpen, nil
 24→	}
 25→	if c.Session == nil {
 26→		return nil, status.UserSessionDeleted
 27→	}
 28→	o := c.Session.Open(fid.Persistent, fid.Volatile)
 29→	if o == nil || o.Closed() {
 30→		// MS-SMB2 §3.3.5.2.10：无效句柄回 STATUS_FILE_CLOSED。
 31→		return nil, status.FileClosed
 32→	}
 33→	// 句柄属于别的树时不得跨用。
 34→	if c.Tree != nil && o.Tree != c.Tree {
 35→		return nil, status.InvalidParameter
 36→	}
 37→	return o, nil
 38→}
