 40→// handleClose 处理 SMB2 CLOSE（MS-SMB2 §3.3.5.10）。
 41→func handleClose(ctx *Context) error {
 42→	req, err := wire.ParseCloseRequest(ctx.Msg)
 43→	if err != nil {
 44→		return status.InvalidParameter
 45→	}
 46→
 47→	open, err := ctx.resolveOpen(req.FileID)
 48→	if err != nil {
 49→		return err
 50→	}
 51→
 52→	resp := &wire.CloseResponse{}
 53→	if req.PostQueryAttrib() {
 54→		// 属性必须在关闭**之前**取，关掉就没了。
 55→		resp.Flags = wire.CloseFlagPostQueryAttrib
 56→		if h := open.Handle; h != nil {
 57→			if attr, aerr := h.Stat(); aerr == nil {
 58→				resp.CreationTime = vfs.TimeToFiletime(attr.CreateTime)
 59→				resp.LastAccessTime = vfs.TimeToFiletime(attr.AccessTime)
 60→				resp.LastWriteTime = vfs.TimeToFiletime(attr.WriteTime)
 61→				resp.ChangeTime = vfs.TimeToFiletime(attr.ChangeTime)
 62→				resp.AllocationSize = uint64(attr.Alloc)
 63→				resp.EndOfFile = uint64(attr.Size)
 64→				resp.FileAttributes = wire.FileAttributes(attr.FileAttributes)
 65→			}
 66→		}
 67→	}
 68→
 69→	// 从句柄表摘除并释放底层资源。
 70→	ctx.Session.RemoveOpen(open.Volatile)
 71→	if ctx.Chain.LastOpen == open {
 72→		ctx.Chain.LastOpen = nil
 73→	}
 74→	delPath, doDelete := open.Path, open.DeleteOnClose() && open.Handle != nil
 75→	open.close()
 76→
 77→	// delete-on-close 的实际删除必须在句柄关闭之后做
 78→	// （Windows 上还持有 fd 时删不掉）。
 79→	if doDelete {
 80→		if err := ctx.deleteOnClose(delPath); err != nil {
 81→			// 删除失败不影响 CLOSE 本身成功 —— 客户端已经认为句柄没了，
 82→			// 回错误只会让它困惑。记日志即可。
 83→			ctx.Log.Warn("delete-on-close 删除失败", "path", delPath, "err", err)
 84→		}
 85→	}
 86→
 87→	ctx.Out = resp.Append(ctx.Out)
 88→	return nil
 89→}
