 91→// deleteOnClose 执行 FILE_DELETE_ON_CLOSE / FileDispositionInformation
 92→// 约定的删除动作。
 93→func (c *Context) deleteOnClose(path string) error {
 94→	if err := c.RequireWritable(); err != nil {
 95→		return err
 96→	}
 97→	fs := c.Tree.FS()
 98→	if fs == nil {
 99→		return status.NetworkNameDeleted
100→	}
101→	return fs.Remove(path)
102→}
