224→			clientCaps:      0x0f,
225→			wantServerCaps:  aaplUnixBased | aaplSupportsReadDirAttr,
226→			wantVolumeCaps:  0,
227→			wantReaddirAttr: true,
228→		},
229→		{
230→			// 客户端没声明支持就绝不能单方面开启：会把目录项写成客户端读不懂的布局。
231→			name:            "客户端不支持 readdir_attr",
232→			appleMeta:       true,
233→			clientCaps:      0,
234→			wantServerCaps:  aaplUnixBased,
235→			wantVolumeCaps:  0,
236→			wantReaddirAttr: false,
237→		},
