239→			name:            "后端拿不出 Apple 元数据",
240→			appleMeta:       false,
241→			clientCaps:      0x0f,
242→			wantServerCaps:  aaplUnixBased,
243→			wantVolumeCaps:  0,
244→			wantReaddirAttr: false,
245→		},
246→		{
247→			name:            "大小写敏感卷",
248→			caseSensitive:   true,
249→			appleMeta:       true,
250→			clientCaps:      0x0f,
251→			wantServerCaps:  aaplUnixBased | aaplSupportsReadDirAttr,
252→			wantVolumeCaps:  aaplCaseSensitive,
253→			wantReaddirAttr: true,
254→		},
255→	}
