339→func newAAPLTestContext(t *testing.T, timeMachine, caseSensitive, appleMeta bool) *Context {
340→	t.Helper()
341→
342→	var fs vfs.FileSystem = &aaplFakeFS{caseSensitive: caseSensitive}
343→	if appleMeta {
344→		fs = &aaplFakeAppleFS{aaplFakeFS{caseSensitive: caseSensitive}}
345→	}
346→	share := &Share{Name: "backup", Type: wire.ShareTypeDisk, FS: fs, TimeMachine: timeMachine}
347→	conn := NewConn(&Settings{Shares: []*Share{share}}, "test", "test")
348→	return &Context{
349→		Conn: conn,
350→		Tree: &Tree{ID: 1, Share: share},
351→		Log:  slog.New(slog.NewTextHandler(io.Discard, nil)),
352→	}
353→}
