362→func (f *aaplFakeFS) Remove(string) error               { return vfs.ErrNotSupported }
363→func (f *aaplFakeFS) Mkdir(string, uint32) error        { return vfs.ErrNotSupported }
364→func (f *aaplFakeFS) Rename(string, string, bool) error { return vfs.ErrNotSupported }
365→func (f *aaplFakeFS) Streams(string) ([]vfs.StreamInfo, error) {
366→	return nil, vfs.ErrNotSupported
367→}
368→func (f *aaplFakeFS) ReadOnly() bool { return false }
369→func (f *aaplFakeFS) Close() error   { return nil }
370→func (f *aaplFakeFS) StatFS() (*vfs.FSInfo, error) {
371→	return &vfs.FSInfo{BlockSize: 4096, CaseSensitive: f.caseSensitive}, nil
372→}
