 15→// 本文件的字节向量**不是编造的**（AGENTS.md §3/§9）。
 16→//
 17→// 来源：Apple《Time Machine over SMB Specification》里的 AAPL create context
 18→// 请求/响应完整示例（该文档同时给出了 Table 1-3 / Table 1-4 两张字段表）：
 19→//
 20→//	--- 请求 ---
 21→//	DataLength:         0x00000018   (24)
 22→//	CommandCode:        0x00000001   kAAPL_SERVER_QUERY
 23→//	Reserved:           0x00000000
 24→//	RequestBitmap:      0x0000000000000007
 25→//	ClientCapabilities: 0x000000000000000f
 26→//
 27→//	--- 响应 ---
 28→//	DataLength:         0x00000020   (32)
 29→//	CommandCode:        0x00000001
 30→//	Reserved:           0x00000000
 31→//	ReplyBitmap:        0x0000000000000003
 32→//	ServerCapabilities: 0x0000000000000000
 33→//	VolumeCapabilities: 0x0000000000000004   kAAPL_SUPPORTS_FULL_SYNC
 34→
 35→// appleSpecRequest 是上面那份请求示例的 24 字节 Data（小端）。
 36→var appleSpecRequest = mustHex(
 37→	"01000000" + // CommandCode = kAAPL_SERVER_QUERY
 38→		"00000000" + // Reserved
 39→		"0700000000000000" + // RequestBitmap = SERVER_CAPS|VOLUME_CAPS|MODEL_INFO
 40→		"0f00000000000000") // ClientCapabilities
 41→
 42→// appleSpecResponse 是上面那份响应示例的 32 字节 Data（小端）。
 43→var appleSpecResponse = mustHex(
 44→	"01000000" + // CommandCode
 45→		"00000000" + // Reserved
 46→		"0300000000000000" + // ReplyBitmap = SERVER_CAPS|VOLUME_CAPS
 47→		"0000000000000000" + // ServerCapabilities
 48→		"0400000000000000") // VolumeCapabilities = kAAPL_SUPPORTS_FULL_SYNC
 49→
 50→func mustHex(s string) []byte {
 51→	b, err := hex.DecodeString(s)
 52→	if err != nil {
 53→		panic(err)
 54→	}
 55→	return b
 56→}
