 58→func TestParseAAPLRequestAppleSpec(t *testing.T) {
 59→	r, err := parseAAPLRequest(appleSpecRequest)
 60→	if err != nil {
 61→		t.Fatalf("parseAAPLRequest: %v", err)
 62→	}
 63→	if r.Command != aaplServerQuery {
 64→		t.Errorf("Command = %d, 期望 %d", r.Command, aaplServerQuery)
 65→	}
 66→	if want := aaplServerCaps | aaplVolumeCaps | aaplModelInfo; r.RequestBitmap != want {
 67→		t.Errorf("RequestBitmap = %#x, 期望 %#x", r.RequestBitmap, want)
 68→	}
 69→	if r.ClientCaps != 0x0f {
 70→		t.Errorf("ClientCapabilities = %#x, 期望 0xf", r.ClientCaps)
 71→	}
 72→	// 0xf 的低位含 kAAPL_SUPPORTS_READ_DIR_ATTR —— readdir_attr 的前提。
 73→	if r.ClientCaps&aaplSupportsReadDirAttr == 0 {
 74→		t.Error("示例客户端能力里应当含 kAAPL_SUPPORTS_READ_DIR_ATTR")
 75→	}
 76→}
