200→func TestNegotiateAAPL(t *testing.T) {
201→	tests := []struct {
202→		name            string
203→		timeMachine     bool
204→		caseSensitive   bool
205→		appleMeta       bool
206→		clientCaps      uint64
207→		wantServerCaps  uint64
208→		wantVolumeCaps  uint64
209→		wantReaddirAttr bool
210→	}{
211→		{
212→			name:            "Time Machine 共享 + 客户端支持 readdir_attr",
213→			timeMachine:     true,
214→			appleMeta:       true,
215→			clientCaps:      0x0f,
216→			wantServerCaps:  aaplUnixBased | aaplSupportsReadDirAttr,
217→			wantVolumeCaps:  aaplSupportsFullSync,
218→			wantReaddirAttr: true,
219→		},
220→		{
221→			// 普通共享不宣告 FULL_SYNC —— 与 Samba 的 fruit:time machine 一致。
222→			name:            "普通共享",
223→			appleMeta:       true,
224→			clientCaps:      0x0f,
225→			wantServerCaps:  aaplUnixBased | aaplSupportsReadDirAttr,
226→			wantVolumeCaps:  0,
227→			wantReaddirAttr: true,
228→		},
229→		{
230→			// 客户端没声明支持就绝不能单方面开启：会把目录项写成客户端读不懂的布局。
231→			name:            "客户端不支持 readdir_attr",
232→			appleMeta:       true,
233→			clientCaps:      0,
234→			wantServerCaps:  aaplUnixBased,
235→			wantVolumeCaps:  0,
236→			wantReaddirAttr: false,
237→		},
238→		{
239→			name:            "后端拿不出 Apple 元数据",
240→			appleMeta:       false,
241→			clientCaps:      0x0f,
242→			wantServerCaps:  aaplUnixBased,
243→			wantVolumeCaps:  0,
244→			wantReaddirAttr: false,
245→		},
246→		{
247→			name:            "大小写敏感卷",
248→			caseSensitive:   true,
249→			appleMeta:       true,
250→			clientCaps:      0x0f,
251→			wantServerCaps:  aaplUnixBased | aaplSupportsReadDirAttr,
252→			wantVolumeCaps:  aaplCaseSensitive,
253→			wantReaddirAttr: true,
254→		},
