259→			ctx := newAAPLTestContext(t, tc.timeMachine, tc.caseSensitive, tc.appleMeta)
260→			req := aaplCreateRequest(aaplServerQuery,
261→				aaplServerCaps|aaplVolumeCaps|aaplModelInfo, tc.clientCaps)
262→
263→			out, err := negotiateAAPL(ctx, req)
264→			if err != nil {
265→				t.Fatalf("negotiateAAPL: %v", err)
266→			}
267→			if len(out) < 32 {
268→				t.Fatalf("响应长度 = %d, 太短", len(out))
269→			}
270→			if v := aaplLE.Uint64(got64(out, 16)); v != tc.wantServerCaps {
271→				t.Errorf("ServerCapabilities = %#x, 期望 %#x", v, tc.wantServerCaps)
272→			}
273→			if v := aaplLE.Uint64(got64(out, 24)); v != tc.wantVolumeCaps {
274→				t.Errorf("VolumeCapabilities = %#x, 期望 %#x", v, tc.wantVolumeCaps)
275→			}
276→			if got := ctx.Conn.AAPLReaddirAttr(); got != tc.wantReaddirAttr {
