326→// aaplCreateRequest 造一个只带 AAPL context 的 CREATE 请求。
327→func aaplCreateRequest(cmd uint32, bitmap, clientCaps uint64) *wire.CreateRequest {
328→	data := make([]byte, aaplRequestSize)
329→	aaplLE.PutUint32(data[0:4], cmd)
330→	aaplLE.PutUint64(data[8:16], bitmap)
331→	aaplLE.PutUint64(data[16:24], clientCaps)
332→	return &wire.CreateRequest{Contexts: []wire.CreateContext{
333→		{Name: wire.CreateContextAAPL, Data: data},
334→	}}
335→}
