  3→import (
  4→	"fmt"
  5→
  6→	"github.com/finalappstore/stupidsamba/internal/smb/crypto"
  7→	"github.com/finalappstore/stupidsamba/internal/smb/status"
  8→	"github.com/finalappstore/stupidsamba/internal/smb/wire"
  9→)
 10→
 11→// Handler 处理一条 SMB2 请求。
 12→//
 13→// 约定：
 14→//   - 成功时把**报文体**追加到 ctx.Out（响应头已由分发器预置），返回 nil；
 15→//   - 失败时返回 error。返回 status.Status 可以精确指定 NTSTATUS，
 16→//     返回其它错误由 status.FromVFSError 统一映射（AGENTS.md §5 P5，
 17→//     禁止在 handler 里裸写魔数）。
 18→//   - 需要返回带响应体的非 SUCCESS 状态（如 SESSION_SETUP 的
 19→//     STATUS_MORE_PROCESSING_REQUIRED、QUERY_INFO 的 STATUS_BUFFER_OVERFLOW）时，
 20→//     直接设置 ctx.Status 并返回 nil。
 21→type Handler func(ctx *Context) error
 22→
 23→// handlerSpec 描述一个命令的处理器及其前置条件。
 24→type handlerSpec struct {
 25→	fn Handler
 26→	// needSession 表示必须有一个**已认证**的会话。
 27→	needSession bool
 28→	// needTree 表示必须有一个有效的树连接。
 29→	needTree bool
 30→	// noResponse 表示本命令**永不产生响应**。
 31→	//
 32→	// 目前只有 SMB2 CANCEL（MS-SMB2 §3.3.5.16）。这类命令跳过全部前置
 33→	// 检查直接执行 handler，且不参与 credit 记账 —— 客户端收不到响应就
 34→	// 拿不回 credit，在这里扣减会让双方水位永久错位。
 35→	noResponse bool
 36→}
 37→
 38→// handlers 是命令分发表（AGENTS.md §5 P2 策略模式）。
 39→//
 40→// 新增一个命令只需要在自己的文件里 init() 调 register()，
 41→// **不需要改动本文件**。未注册的命令统一走 defaultHandler。
 42→var handlers = map[wire.Command]handlerSpec{}
 43→
 44→// register 登记一个命令处理器。重复注册会 panic —— 这是编码错误，
 45→// 发生在进程启动阶段（init），不会影响运行中的服务。
 46→func register(cmd wire.Command, needSession, needTree bool, fn Handler) {
 47→	if _, dup := handlers[cmd]; dup {
 48→		panic(fmt.Sprintf("command: %s 重复注册", cmd))
 49→	}
 50→	handlers[cmd] = handlerSpec{fn: fn, needSession: needSession, needTree: needTree}
 51→}
 52→
 53→// registerNoResponse 登记一个**不产生响应**的命令处理器（见 handlerSpec.noResponse）。
 54→func registerNoResponse(cmd wire.Command, fn Handler) {
 55→	if _, dup := handlers[cmd]; dup {
 56→		panic(fmt.Sprintf("command: %s 重复注册", cmd))
 57→	}
 58→	handlers[cmd] = handlerSpec{fn: fn, noResponse: true}
 59→}
 60→
 61→// Registered 报告某个命令是否已经实现，用于日志与测试。
 62→func Registered(cmd wire.Command) bool {
 63→	_, ok := handlers[cmd]
 64→	return ok
 65→}
 66→
 67→// NoResponse 报告某个命令是否永不产生响应（MS-SMB2 §3.3.5.16 的 CANCEL）。
 68→//
 69→// internal/server 用它决定是否要为这条消息记 credit 账。
 70→func NoResponse(cmd wire.Command) bool {
 71→	return handlers[cmd].noResponse
 72→}
 73→
 74→// defaultHandler 处理所有未实现的命令（AGENTS.md §5 P2）。
 75→func defaultHandler(ctx *Context) error {
 76→	ctx.Log.Debug("未实现的 SMB2 命令", "command", ctx.Header.Command.String(),
 77→		"remote", ctx.Conn.RemoteAddr)
 78→	return status.NotSupported
 79→}
 80→
 81→// Dispatch 处理一条请求并把响应写入 ctx.Out。
 82→//
 83→// 无论成功失败都会产生一条格式正确的响应 —— SMB2 不允许对请求静默不答，
 84→// 客户端会一直等到超时。
