 78→	// delete-on-close 的实际删除必须在句柄关闭之后做
 79→	// （Windows 上还持有 fd 时删不掉）。
 80→	if doDelete {
 81→		if err := ctx.deleteOnClose(delPath); err != nil {
 82→			// 删除失败不影响 CLOSE 本身成功 —— 客户端已经认为句柄没了，
 83→			// 回错误只会让它困惑。记日志即可。
 84→			ctx.Log.Warn("delete-on-close 删除失败", "path", delPath, "err", err)
 85→		}
 86→	}
 87→
 88→	ctx.Out = resp.Append(ctx.Out)
 89→	return nil
 90→}
 91→
 92→// deleteOnClose 执行 FILE_DELETE_ON_CLOSE / FileDispositionInformation
 93→// 约定的删除动作。
 94→func (c *Context) deleteOnClose(path string) error {
 95→	if err := c.RequireWritable(); err != nil {
 96→		return err
 97→	}
 98→	fs := c.Tree.FS()
 99→	if fs == nil {
100→		return status.NetworkNameDeleted
101→	}
102→	return fs.Remove(path)
103→}
