{"file_path": "/workspace/internal/smb/command/lock_test.go", "content": "package command

import (
	"math"
	"testing"

	"github.com/finalappstore/stupidsamba/internal/smb/status"
	"github.com/finalappstore/stupidsamba/internal/smb/wire"
)

// el 拼一条 LockElement。excl 为 true 时是独占锁，否则共享锁。
func el(off, length uint64, excl bool) wire.LockElement {
	f := wire.LockFlagSharedLock
	if excl {
		f = wire.LockFlagExclusiveLock
	}
	return wire.LockElement{Offset: off, Length: length, Flags: f}
}

// unlockEl 拼一条 UNLOCK 元素。
func unlockEl(off, length uint64) wire.LockElement {
	return wire.LockElement{Offset: off, Length: length, Flags: wire.LockFlagUnlock}
}

// TestLockExclusiveBlocksOtherHandle：A 持独占锁后，B 不能锁重叠区间，
// 但可以锁不相交的区间。
func TestLockExclusiveBlocksOtherHandle(t *testing.T) {
	var tbl lockTable
	a, b := &Open{}, &Open{}

	if st := tbl.lock("f", a, []wire.LockElement{el(0, 100, true)}); st != status.Success {
		t.Fatalf("A 首次加独占锁应成功，实际 %v", st)
	}
	if st := tbl.lock("f", b, []wire.LockElement{el(50, 100, true)}); st != status.LockNotGranted {
		t.Fatalf("B 锁重叠区间应回 STATUS_LOCK_NOT_GRANTED，实际 %v", st)
	}
	if st := tbl.lock("f", b, []wire.LockElement{el(100, 100, true)}); st != status.Success {
		t.Fatalf("B 锁 [100,200) 与 [0,100) 不相交，应成功，实际 %v", st)
	}
	// 不同文件互不影响。
	if st := tbl.lock("g", b, []wire.LockElement{el(0, 100, true)}); st != status.Success {
		t.Fatalf("另一个文件上的同区间应成功，实际 %v", st)
	}
}

// TestLockSharedCoexistExclusiveDoesNot：共享锁之间可以重叠共存，
// 独占锁与任何重叠锁互斥。
func TestLockSharedCoexistExclusiveDoesNot(t *testing.T) {
	var tbl lockTable
	a, b, c := &Open{}, &Open{}, &Open{}

	if st := tbl.lock("f", a, []wire.LockElement{el(0, 100, false)}); st != status.Success {
		t.Fatalf("A 共享锁应成功，实际 %v", st)
	}
	if st := tbl.lock("f", b, []wire.LockElement{el(0, 100, false)}); st != status.Success {
		t.Fatalf("B 重叠共享锁应共存，实际 %v", st)
	}
	if st := tbl.lock("f", c, []wire.LockElement{el(50, 10, true)}); st != status.LockNotGranted {
		t.Fatalf("C 在共享锁上加独占锁应被拒，实际 %v", st)
	}
}

// TestLockSameHandleNoSelfConflict：同一个句柄自己的锁不与自己冲突。
func TestLockSameHandleNoSelfConflict(t *testing.T) {
	var tbl lockTable
	a := &Open{}

	if st := tbl.lock("f", a, []wire.LockElement{el(0, 100, true)}); st != status.Success {
		t.Fatalf("首次加锁应成功，实际 %v", st)
	}
	if st := tbl.lock("f", a, []wire.LockElement{el(0, 100, true)}); st != status.Success {
		t.Fatalf("同句柄重复锁同区间应成功，实际 %v", st)
	}
}

// TestLockAllOrNothing：一条请求里任何一条元素冲突，整条请求都不得留下
// 部分已授予的锁（MS-SMB2 §3.3.5.14）。
func TestLockAllOrNothing(t *testing.T) {
	var tbl lockTable
	a, b := &Open{}, &Open{}

	if st := tbl.lock("f", a, []wire.LockElement{el(200, 50, true)}); st != status.Success {
		t.Fatalf("A 加锁应成功，实际 %v", st)
	}
	// B 请求两条：第一条本可授予，第二条与 A 冲突 → 整条失败。
	st := tbl.lock("f", b, []wire.LockElement{el(0, 50, true), el(200, 50, true)})
	if st != status.LockNotGranted {
		t.Fatalf("含冲突的批量加锁应整体失败，实际 %v", st)
	}
	// 关键断言：第一条不能被留下。用另一个句柄去锁 [0,50) 验证它是空闲的。
	c := &Open{}
	if st := tbl.lock("f", c, []wire.LockElement{el(0, 50, true)}); st != status.Success {
		t.Fatalf("失败的批量请求不应留下部分锁，[0,50) 应仍空闲，实际 %v", st)
	}
}

// TestUnlockRequiresExactRange：解锁区间必须与加锁时完全一致，
// 否则 STATUS_RANGE_NOT_LOCKED。
func TestUnlockRequiresExactRange(t *testing.T) {
	var tbl lockTable
	a := &Open{}

	if st := tbl.lock("f", a, []wire.LockElement{el(0, 100, true)}); st != status.Success {
		t.Fatalf("加锁应成功，实际 %v", st)
	}
	if st := tbl.unlock("f", a, []wire.LockElement{unlockEl(0, 50)}); st != status.RangeNotLocked {
		t.Fatalf("部分区间解锁应回 STATUS_RANGE_NOT_LOCKED，实际 %v", st)
	}
	// 别人的锁也解不掉。
	b := &Open{}
	if st := tbl.unlock("f", b, []wire.LockElement{unlockEl(0, 100)}); st != status.RangeNotLocked {
		t.Fatalf("解别人的锁应回 STATUS_RANGE_NOT_LOCKED，实际 %v", st)
	}
	if st := tbl.unlock("f", a, []wire.LockElement{unlockEl(0, 100)}); st != status.Success {
		t.Fatalf("精确解锁应成功，实际 %v", st)
	}
	// 解锁后别人就能锁了。
	if st := tbl.lock("f", b, []wire.LockElement{el(0, 100, true)}); st != status.Success {
		t.Fatalf("解锁后 B 应能加锁，实际 %v", st)
	}
}

// TestReleaseAllOnClose：releaseAll 释放该句柄的全部锁，且不动别人的。
func TestReleaseAllOnClose(t *testing.T) {
	var tbl lockTable
	a, b := &Open{}, &Open{}

	if st := tbl.lock("f", a, []wire.LockElement{el(0, 10, true), el(100, 10, true)}); st != status.Success {
		t.Fatalf("A 加锁应成功，实际 %v", st)
	}
	if st := tbl.lock("f", b, []wire.LockElement{el(200, 10, true)}); st != status.Success {
		t.Fatalf("B 加锁应成功，实际 %v", st)
	}

	tbl.releaseAll("f", a)

	c := &Open{}
	if st := tbl.lock("f", c, []wire.LockElement{el(0, 10, true), el(100, 10, true)}); st != status.Success {
		t.Fatalf("A 的锁应已全部释放，实际 %v", st)
	}
	if st := tbl.lock("f", c, []wire.LockElement{el(200, 10, true)}); st != status.LockNotGranted {
		t.Fatalf("B 的锁不应被 A 的 releaseAll 带走，实际 %v", st)
	}
}

// TestLockTableEmptiesOut：所有锁释放后表内不留空条目，避免长跑泄漏。
func TestLockTableEmptiesOut(t *testing.T) {
	var tbl lockTable
	a := &Open{}

	if st := tbl.lock("f", a, []wire.LockElement{el(0, 10, true)}); st != status.Success {
		t.Fatalf("加锁应成功，实际 %v", st)
	}
	tbl.releaseAll("f", a)
	if _, ok := tbl.m["f"]; ok {
		t.Fatal("锁全部释放后不应残留路径条目")
	}
}

// TestLockZeroLengthNeverConflicts：长度为 0 的锁不锁定任何字节，
// 与谁都不冲突（MS-FSA §2.1.4.10）。
func TestLockZeroLengthNeverConflicts(t *testing.T) {
	var tbl lockTable
	a, b := &Open{}, &Open{}

