	var tbl lockTable
	a, b := &Open{}, &Open{}

	const max = uint64(math.MaxUint64)
	if st := tbl.lock("f", a, []wire.LockElement{el(max-10, 20, true)}); st != status.Success {
		t.Fatalf("A 加锁应成功，实际 %v", st)
	}
	if st := tbl.lock("f", b, []wire.LockElement{el(max-5, 20, true)}); st != status.LockNotGranted {
		t.Fatalf("回绕区间仍应判为相交，实际 %v", st)
	}
	// 反向：真正不相交的高位区间要能通过。
	if st := tbl.lock("f", b, []wire.LockElement{el(0, 10, true)}); st != status.Success {
		t.Fatalf("低位不相交区间应成功，实际 %v", st)
	}
}

// TestLockCommandsRegistered：三个命令都必须挂上分发表，
// 否则会落到 defaultHandler。
func TestLockCommandsRegistered(t *testing.T) {
	for _, c := range []wire.Command{
		wire.CommandLock, wire.CommandChangeNotify, wire.CommandOplockBreak,
	} {
		if !Registered(c) {
