import (
	"math"
	"testing"

	"github.com/finalappstore/stupidsamba/internal/smb/wire"
)

// grant 在 tbl 上模拟一次"冲突判定 + 登记"，返回是否授予。
//
// 这正是 handleLock 对每条 LockElement 做的事，抽出来让锁语义可以脱离
// 完整的 Context/Session 装配单独测试。
func grant(tbl *lockTable, path string, owner *Open, off, length uint64, excl bool) bool {
	tbl.mu.Lock()
	defer tbl.mu.Unlock()

	if tbl.conflict(path, owner, off, length, excl) {
		return false
	}
	tbl.add(path, byteRangeLock{
		owner: owner, offset: off, length: length, exclusive: excl,
	})
	return true
}

// release 摘除一条精确匹配的锁，返回是否找到。
func release(tbl *lockTable, path string, owner *Open, off, length uint64) bool {
	tbl.mu.Lock()
	defer tbl.mu.Unlock()

	return tbl.remove(path, owner, off, length)
}

// TestLockExclusiveBlocksOtherHandle：A 持独占锁后，B 不能锁重叠区间，
// 但可以锁不相交的区间；不同文件互不影响。
func TestLockExclusiveBlocksOtherHandle(t *testing.T) {
	var tbl lockTable
	a, b := &Open{}, &Open{}

	if !grant(&tbl, "f", a, 0, 100, true) {
		t.Fatal("A 首次加独占锁应成功")
	}
	if grant(&tbl, "f", b, 50, 100, true) {
		t.Fatal("B 锁重叠区间 [50,150) 应被拒")
	}
	if !grant(&tbl, "f", b, 100, 100, true) {
		t.Fatal("B 锁 [100,200) 与 [0,100) 不相交，应成功")
	}
	if !grant(&tbl, "g", b, 0, 100, true) {
		t.Fatal("另一个文件上的同区间不应受影响")
	}
}

// TestLockSharedCoexistExclusiveDoesNot：共享锁之间可以重叠共存，
// 独占锁与任何重叠锁互斥。
func TestLockSharedCoexistExclusiveDoesNot(t *testing.T) {
	var tbl lockTable
	a, b, c := &Open{}, &Open{}, &Open{}

	if !grant(&tbl, "f", a, 0, 100, false) {
		t.Fatal("A 共享锁应成功")
	}
	if !grant(&tbl, "f", b, 0, 100, false) {
		t.Fatal("B 重叠共享锁应能共存")
	}
	if grant(&tbl, "f", c, 50, 10, true) {
		t.Fatal("在共享锁上加独占锁应被拒")
	}
}

// TestLockSameHandleNoSelfConflict：同一个句柄自己的锁不与自己冲突。
func TestLockSameHandleNoSelfConflict(t *testing.T) {
	var tbl lockTable
	a := &Open{}

	if !grant(&tbl, "f", a, 0, 100, true) {
		t.Fatal("首次加锁应成功")
	}
	if !grant(&tbl, "f", a, 0, 100, true) {
		t.Fatal("同句柄重复锁同区间应成功")
	}
}

// TestUnlockRequiresExactRange：解锁区间必须与加锁时完全一致，
// 部分解锁、解别人的锁都必须失败（MS-SMB2 §3.3.5.14.2）。
func TestUnlockRequiresExactRange(t *testing.T) {
	var tbl lockTable
	a, b := &Open{}, &Open{}

	if !grant(&tbl, "f", a, 0, 100, true) {
		t.Fatal("加锁应成功")
	}
	if release(&tbl, "f", a, 0, 50) {
		t.Fatal("部分区间解锁必须失败")
	}
	if release(&tbl, "f", b, 0, 100) {
		t.Fatal("不能解别人持有的锁")
	}
	if !release(&tbl, "f", a, 0, 100) {
		t.Fatal("精确解锁应成功")
	}
	if !grant(&tbl, "f", b, 0, 100, true) {
		t.Fatal("解锁后 B 应能加锁")
	}
}

// TestReleaseAllOnClose：releaseAll 释放该句柄的全部锁，且不动别人的。
// 句柄关闭时若不释放，崩掉的客户端会把文件永久锁死。
func TestReleaseAllOnClose(t *testing.T) {
	var tbl lockTable
	a, b := &Open{}, &Open{}

	if !grant(&tbl, "f", a, 0, 10, true) || !grant(&tbl, "f", a, 100, 10, true) {
		t.Fatal("A 加两把锁应成功")
	}
	if !grant(&tbl, "f", b, 200, 10, true) {
		t.Fatal("B 加锁应成功")
	}
	if n := tbl.count(a); n != 2 {
		t.Fatalf("A 应持有 2 把锁，实际 %d", n)
	}

	tbl.releaseAll("f", a)

	if n := tbl.count(a); n != 0 {
		t.Fatalf("releaseAll 后 A 应持有 0 把锁，实际 %d", n)
	}
	if n := tbl.count(b); n != 1 {
		t.Fatalf("B 的锁不应被 A 的 releaseAll 带走，实际 %d", n)
	}

	c := &Open{}
	if !grant(&tbl, "f", c, 0, 10, true) || !grant(&tbl, "f", c, 100, 10, true) {
		t.Fatal("A 的区间应已可用")
	}
	if grant(&tbl, "f", c, 200, 10, true) {
		t.Fatal("B 的区间仍应被占用")
	}
}

// TestLockTableEmptiesOut：锁全部释放后不留空桶，避免长跑内存泄漏。
func TestLockTableEmptiesOut(t *testing.T) {
	var tbl lockTable
	a := &Open{}

	if !grant(&tbl, "f", a, 0, 10, true) {
		t.Fatal("加锁应成功")
	}
	tbl.releaseAll("f", a)
	if _, ok := tbl.byPath["f"]; ok {
		t.Fatal("锁全部释放后不应残留路径桶")
	}

	// remove 路径也要清桶。
	if !grant(&tbl, "f", a, 0, 10, true) {
		t.Fatal("重新加锁应成功")
	}
	if !release(&tbl, "f", a, 0, 10) {
		t.Fatal("解锁应成功")
	}
	if _, ok := tbl.byPath["f"]; ok {
		t.Fatal("remove 摘掉最后一把锁后也应清掉路径桶")
	}
}

// TestLockZeroLengthNeverConflicts：长度为 0 的锁不占据任何字节，
// 与谁都不冲突（MS-FSA §2.1.4.10）。
func TestLockZeroLengthNeverConflicts(t *testing.T) {
	var tbl lockTable
	a, b := &Open{}, &Open{}

	if !grant(&tbl, "f", a, 0, 0, true) {
		t.Fatal("零长度加锁应成功")
	}
	if !grant(&tbl, "f", b, 0, 100, true) {
		t.Fatal("零长度锁不应挡住别人")
	}
	if !grant(&tbl, "f", a, 50, 0, true) {
		t.Fatal("在别人独占区间内加零长度锁也应成功")
	}
}

// TestLockOverlapNoIntegerOverflow：offset+length 在 uint64 上回绕时
// 不能把"相交"误判成"不相交"（AGENTS.md §8 整数溢出防御）。
//
// 若实现用裸加法算区间终点，[max-10, max-10+20) 的终点会回绕成一个极小值，
// 冲突判定就会错误放行 —— 那等于锁在文件尾部完全失效。
func TestLockOverlapNoIntegerOverflow(t *testing.T) {
	var tbl lockTable
	a, b := &Open{}, &Open{}

	const max = uint64(math.MaxUint64)

	if !grant(&tbl, "f", a, max-10, 20, true) {
		t.Fatal("A 在回绕区间加锁应成功")
	}
	if grant(&tbl, "f", b, max-5, 20, true) {
		t.Fatal("回绕区间仍然相交，B 必须被拒")
	}
	if !grant(&tbl, "f", b, 0, 10, true) {
		t.Fatal("低位不相交区间应放行")
	}

	// 反向顺序同样成立：先锁高位小区间，再锁跨越它的大区间。
	var tbl2 lockTable
	if !grant(&tbl2, "f", a, max-5, 5, true) {
		t.Fatal("A 加锁应成功")
	}
	if grant(&tbl2, "f", b, max-10, 20, true) {
		t.Fatal("包含关系也是相交，B 必须被拒")
	}
}

// TestLockAdjacentRangesDoNotConflict：相邻但不重叠的区间必须能同时持有。
// 这是"off by one"最容易翻车的地方。
func TestLockAdjacentRangesDoNotConflict(t *testing.T) {
	var tbl lockTable
	a, b := &Open{}, &Open{}

	if !grant(&tbl, "f", a, 0, 100, true) {
		t.Fatal("A 锁 [0,100) 应成功")
	}
	if !grant(&tbl, "f", b, 100, 100, true) {
		t.Fatal("B 锁 [100,200) 与 [0,100) 相邻不相交，应成功")
	}
	if grant(&tbl, "f", b, 99, 1, true) {
		t.Fatal("[99,100) 落在 A 的区间内，应被拒")
	}
}

// TestLockCommandsRegistered：LOCK / CHANGE_NOTIFY / OPLOCK_BREAK
// 都必须挂上分发表，否则会落到 defaultHandler 回 STATUS_NOT_SUPPORTED
// 而不是各自的语义；且它们都**必须**产生响应（不是 CANCEL 那种无响应命令）。
func TestLockCommandsRegistered(t *testing.T) {
	for _, c := range []wire.Command{
		wire.CommandLock, wire.CommandChangeNotify, wire.CommandOplockBreak,
	} {
		if !Registered(c) {
			t.Errorf("%s 未注册到分发表", c)
		}
		if NoResponse(c) {
			t.Errorf("%s 不应被标记为无响应命令", c)
		}
	}
}
"}

